interface SearchReply {
  queryId: string;
  cards: ResultCard[];
  facets: FacetCount[];
  total: number;
  nextPage: number | null;
}

interface SearchGateway {
  search(input: { query: SearchQuery; queryId: string; signal: AbortSignal }): Promise<SearchReply>;
  loadPage(input: { query: SearchQuery; queryId: string; page: number; signal: AbortSignal }): Promise<SearchReply>;
  suggestCities(input: { text: string; signal: AbortSignal }): Promise<string[]>;
}

interface UnitContract {
  contractVersion: number;
  mount(slot: HTMLElement, props: { query: SearchQuery; onQueryChange(next: SearchQuery, mode: 'replace' | 'push'): void }): void;
  update(props: { query: SearchQuery; results: ResultsState | null }): void;
  unmount(): void;
}

type TelemetryEvent =
  | { type: 'vital'; name: 'LCP' | 'INP' | 'CLS'; value: number; unit: string; buildId: string }
  | { type: 'funnel'; stage: 'search' | 'view' | 'book' | 'pay'; searchId: string; unit: string; buildId: string }
  | { type: 'error'; code: string; unit: string; buildId: string };

interface Telemetry {
  report(event: TelemetryEvent): void;
}
